SELECT s.actor_id,s.project_id,s.workspace_id,s.machine_id,s.enrollment_id,s.harness_session_id,s.create_operation_id,s.create_contents_digest,s.create_attempt,s.agent_program,s.session_kind,s.creator_kind,s.creator_actor_id,s.secret_hash,s.session_state,s.reserved_until,s.bound_at,s.settled_cause,s.settled_at,d.parent_actor_id FROM actor_sessions s LEFT JOIN actor_delegates d ON d.actor_id=s.actor_id WHERE s.machine_id=? AND s.actor_id=?
